    def worker():
        barrier.wait()
        try:
            for _ in range(200):
                with counter_lock:
                    key = f"k{counter['i']}"
                    counter["i"] += 1
                entry = cache.alloc(key, 1)
                if entry is not None:
                    cache.mark_ready(key)
        except Exception as exc:
            errors.append(exc)

    threads = [threading.Thread(target=worker) for _ in range(4)]
    for t in threads:
